def assemble_prompt(available_tools, retrieved_memory, trajectory):
    sections = [f"Goal: {trajectory.goal}"]
    if retrieved_memory:
        sections.append(f"Relevant memory: {retrieved_memory}")
    if available_tools:
        sections.append(f"Available tools: {available_tools}")
    sections.append(f"Progress so far: {trajectory.summary()}")
    return "\n\n".join(sections)
